import java.util.*;

class Solution {
  public int[] gridIllumination(int n, int[][] lamps, int[][] queries) {
    Map<Long, Integer> rows = new HashMap<>(),
        cols = new HashMap<>(),
        diag = new HashMap<>(),
        anti = new HashMap<>();
    Set<Long> on = new HashSet<>();
    for (int[] p : lamps) {
      long id = ((long) p[0] << 32) | (p[1] & 0xffffffffL);
      if (on.add(id)) {
        add(rows, p[0]);
        add(cols, p[1]);
        add(diag, p[0] - p[1]);
        add(anti, p[0] + p[1]);
      }
    }
    int[] ans = new int[queries.length];
    int k = 0;
    for (int[] q : queries) {
      int r = q[0], c = q[1];
      ans[k++] =
          (rows.getOrDefault((long) r, 0) > 0
                  || cols.getOrDefault((long) c, 0) > 0
                  || diag.getOrDefault((long) r - c, 0) > 0
                  || anti.getOrDefault((long) r + c, 0) > 0)
              ? 1
              : 0;
      for (int dr = -1; dr <= 1; dr++)
        for (int dc = -1; dc <= 1; dc++) {
          int nr = r + dr, nc = c + dc;
          if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
            long id = ((long) nr << 32) | (nc & 0xffffffffL);
            if (on.remove(id)) {
              sub(rows, nr);
              sub(cols, nc);
              sub(diag, nr - nc);
              sub(anti, nr + nc);
            }
          }
        }
    }
    return ans;
  }

  private void add(Map<Long, Integer> m, long k) {
    m.put(k, m.getOrDefault(k, 0) + 1);
  }

  private void sub(Map<Long, Integer> m, long k) {
    int v = m.get(k) - 1;
    if (v == 0) m.remove(k);
    else m.put(k, v);
  }
}
